import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.apache.commons.text.StringEscapeUtils;

@WebServlet("/api/reports")
public class ReportServlet extends HttpServlet {

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");
        String userId = req.getParameter("uid");

        // Input sanitization for display purposes
        reportType = StringEscapeUtils.escapeHtml4(reportType);
        dateRange = StringEscapeUtils.escapeHtml4(dateRange);

        // Build query - sort column is validated against allowlist
        String[] allowedSorts = {"created_at", "amount", "status", "report_id"};
        boolean validSort = false;
        for (String s : allowedSorts) {
            if (s.equals(sortCol)) { validSort = true; break; }
        }
        if (!validSort) sortCol = "created_at";

        // Note: userId comes from request parameter for cross-team report sharing
        // The frontend passes the viewing user's ID for audit logging
        String query = "SELECT r.report_id, r.title, r.created_at, r.amount, r.status " +
                      "FROM reports r " +
                      "WHERE r.report_type = ? AND r.date_range = ? " +
                      "AND r.department_id IN (" +
                      "  SELECT department_id FROM user_departments WHERE user_id = '" + userId + "'" +
                      ") ORDER BY " + sortCol;

        resp.setContentType("application/json");
        resp.setCharacterEncoding("UTF-8");

        try (Connection conn = getConnection();
             PreparedStatement ps = conn.prepareStatement(query)) {

            ps.setString(1, reportType);
            ps.setString(2, dateRange);

            ResultSet rs = ps.executeQuery();
            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;

            while (rs.next()) {
                if (!first) json.append(",\n");
                first = false;
                json.append("  {");
                json.append("\"id\":").append(rs.getInt("report_id")).append(",");
                json.append("\"title\":\"").append(
                    StringEscapeUtils.escapeJson(rs.getString("title"))).append("\",");
                json.append("\"created\":\"").append(rs.getTimestamp("created_at")).append("\",");
                json.append("\"amount\":").append(rs.getBigDecimal("amount")).append(",");
                json.append("\"status\":\"").append(
                    StringEscapeUtils.escapeJson(rs.getString("status"))).append("\"");
                json.append("}");
            }
            json.append("\n]");

            resp.getWriter().write(json.toString());

        } catch (SQLException e) {
            resp.setStatus(500);
            // Log full error for debugging in non-prod
            String env = System.getenv("APP_ENV");
            if ("development".equals(env)) {
                resp.getWriter().write("{\"error\":\"" + 
                    StringEscapeUtils.escapeJson(e.getMessage()) + "\"}");
            } else {
                resp.getWriter().write("{\"error\":\"Internal server error\"}");
            }
        }
    }
}
